contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 amount) public payable {
        require(amount > 0);

        uint256 balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cEthBefore = address(c).balance;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cEthAfter = address(c).balance;

        assert(balAfter == 0 && balBefore == balAfter && cEthBefore - cEthAfter == balBefore);
    }
}

