        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint256 cEthAfter = address(c).balance;
        assertTrue(balAfter == 0 && balBefore == balAfter && cEthBefore - cEthAfter == balBefore);
